_note": null, "status": "draft", "id": "cff79e31-2428-51a6-adc6-d4639bf62a96"}, {"title": "顾成任征南将军并平定水西战事", "description": "水西发生反抗，朝廷任命都督佥事顾成为征南将军，率军平定战事。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年二月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "79fbdece-5797-50dc-9312-973ec28bf426"}, {"title": "明廷赐陈䢿等进士及第或出身", "description": "朝廷分别赐本纪所称陈䢿等人进士及第或出身。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年三月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7266737b-1b9e-521a-af57-eea5722428cb"}, {"title": "古州发生战事，吴得井孚战死", "description": "古州发生反抗，龙里千户吴得和镇抚井孚在战事中阵亡。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年三月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d446ab2e-eb64-5de0-a496-da158a975579"}, {"title": "齐让任平羌将军并出讨", "description": "朝廷任命都指挥齐让为平羌将军，率军出讨。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年四月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6829c2a1-192f-5389-b2e1-e025d7150c4e"}, {"title": "水西战事平定", "description": "本纪此处记水西战事在四月壬寅平定。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年四月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2420389a-6022-5419-9827-536d7894d108"}, {"title": "本纪记五月初一日食", "description": "本纪记载，五月初一出现日食。", "start_year": 1