unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "091b8b96-0bc5-5e3d-b2d2-b11f4228baf4"}, {"title": "汉沔战事平定", "description": "本纪记载，汉、沔一带的战事于九月庚戌平定。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年九月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f1d8cc20-a607-5ae0-a524-659f950db139"}, {"title": "刀干孟驱逐思伦发并起兵", "description": "麓川平缅首领刀干孟驱逐当地宣慰使思伦发，起兵反明。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年九月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "208e2692-a202-5940-9070-0bc174323987"}, {"title": "杨文出任征虏将军接替齐让", "description": "朝廷任命都督杨文为征虏将军，接替齐让。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年九月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "086c8e88-4d00-57d2-9d5d-454e4371fd39"}, {"title": "明廷停止辽东海运", "description": "朝廷下令暂停辽东海运。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年十月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "59e04d22-a7f8-531b-b482-3abd44874d22"}, {"title": "耿炳文在陕西练兵", "description": "耿炳文在陕西训练军队。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年十月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f123967-23a5-5d05-961b-2d461da2737d"}, {"title": "国子监先师庙重建落成", "description": "国子监的先师庙重建落成。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年十月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ae4a3924-1be5-5a9a-aca5-99e052caf86c"}, {"title": "沐春何福等奉命出兵讨刀干孟", "description": "朝廷以沐春为征虏前将军、都督何福等为副将，率军出讨刀干孟。", "start_year": 1397, "end_year": 1397, "time_original": "洪武三十年十一月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b1e18283-d60b-543e-b3e3-689a7ef34991"}, {"title": "琉球等地来贡", "description": "本纪记载，琉球、占城、朝鲜、暹罗、乌斯藏和泥八剌当年来贡。 按原历纪年，事情发生在公元1397至1398年之间。", "start_year": null, "end_year": null, "time_original": "洪武三十年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e575af5-f2a4-554d-bbfc-c02a265523bb"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年正月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a041cec9-8940-50ad-9f4e-bf0d1f7bbc41"}, {"title": "明廷派使者到山东河南督促耕种", "description": "朝廷派使者前往山东和河南督促百姓耕种。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年正月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23d4f599-301c-5788-a086-a67a94bee6d3"}, {"title": "陶铎在宁海击退倭寇", "description": "倭寇进攻宁海，指挥陶铎率军将其击败。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3d3f355-663d-524b-8b84-2d18a6159af9"}, {"title": "古州战事平定，朝廷召回杨文", "description": "古州战事平定，朝廷召杨文返回。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c936d1a8-bc44-5e40-ada5-4a92a9899020"}, {"title": "徐凯率军平定本纪所载战事", "description": "都督佥事徐凯率军平定本纪所称么些的战事。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年二月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d4a7c7db-89e3-57df-a2f3-c32d405bc999"}, {"title": "朝廷拒绝廷臣出兵讨朝鲜的请求", "description": "廷臣以朝鲜多次发生争端为由，请求出兵征讨，朝廷没有批准。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年四月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c3d5a286-0089-5e44-bd1a-6b93e0a20b7d"}, {"title": "沐春击败刀干孟", "description": "沐春率军进攻刀干孟，取得大胜。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年五月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3052a221-2f54-5660-9e64-33c6bd2dd448"}, {"title": "朱元璋患病", "description": "本纪记载，朱元璋于五月甲寅患病。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年五月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ca6a8db-b223-5a3f-ab17-99911cb6cbca"}, {"title": "明廷命燕王节制守备开平的两部军队", "description": "都督杨文随燕王朱棣，武定侯郭英随辽王朱植，部署开平防务。两部都受燕王节制。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年五月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1251da82-cb2b-5503-a97b-d4b60c7d3a9b"}, {"title": "朱元璋病重", "description": "本纪记载，朱元璋在闰五月癸未病情加重。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9b5f1d4-cffe-5f78-a6c8-64cd06a3dd58"}, {"title": "朱元璋在西宫去世", "description": "朱元璋在西宫去世，本纪记年龄为七十一。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "987e40aa-7934-5658-aacb-99979d5064e0"}, {"title": "朱元璋遗诏指定朱允炆继位", "description": "朱元璋遗诏规定由皇太孙朱允炆继位，要求中央和地方的文武臣僚同心辅政，安定百姓。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9f7fbbc4-ee84-5a19-8da4-6051cc4061c1"}, {"title": "朱元璋遗诏规定丧祭与服丧办法", "description": "朱元璋遗诏规定，丧祭不用金玉，孝陵山川依照原有形势。臣民哭临三天后脱去丧服，婚嫁照常。各藩王在各自封国内举哀，无须前往京师。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d4102381-df1a-58e5-9c7b-e969fb79a48f"}, {"title": "朱元璋葬于孝陵", "description": "朱元璋葬于孝陵，谥号为高皇帝，庙号为太祖。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6f327147-bd5a-5d73-b55c-8599a38e8e70"}, {"title": "本纪记安南黎季犛又弑其君", "description": "本纪在本年记黎季犛再次杀害安南君主，这次的君主名为日。 按原历纪年，事情发生在公元1389至1390年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "857ca945-24c9-5089-9e20-2f429a75f007"}]'::jsonb)
